__check('encode zwei woerter', encode('best owl') == __enc('best owl'))
__check('encode einzelwort', encode('best') == __enc('best'))
__check('round trip einzelwort', decode(encode('best')) == 'best')
__check('round trip zwei woerter', decode(encode('best owl')) == 'best owl')
